from pathlib import Path
from docx import Document
from docx.shared import Cm, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

out = Path(__file__).parent / 'output' / 'Exact_Alphabet_Partitioning_Article_FA_v2.docx'
doc = Document()
sec = doc.sections[0]
sec.top_margin = Cm(2.2); sec.bottom_margin = Cm(2.2); sec.left_margin = Cm(2.4); sec.right_margin = Cm(2.4)
styles = doc.styles
for name in ['Normal','Title','Heading 1','Heading 2']:
    st=styles[name]; st.font.name='Arial'; st._element.rPr.rFonts.set(qn('w:eastAsia'),'Arial')
styles['Normal'].font.size=Pt(11)
styles['Normal'].paragraph_format.space_after=Pt(6)
styles['Heading 1'].font.color.rgb=RGBColor(31,78,121)

def rtl(p, align=WD_ALIGN_PARAGRAPH.RIGHT):
    p.alignment=align
    pPr=p._p.get_or_add_pPr(); el=OxmlElement('w:bidi'); pPr.append(el)
    jc=OxmlElement('w:jc'); jc.set(qn('w:val'),'right'); pPr.append(jc)
    for run in p.runs:
        rp=run._r.get_or_add_rPr()
        if rp.find(qn('w:rtl')) is None: rp.append(OxmlElement('w:rtl'))
        fonts=rp.find(qn('w:rFonts'))
        if fonts is None: fonts=OxmlElement('w:rFonts'); rp.append(fonts)
        fonts.set(qn('w:cs'),'Arial'); fonts.set(qn('w:eastAsia'),'Arial')
        lang=rp.find(qn('w:lang'))
        if lang is None: lang=OxmlElement('w:lang'); rp.append(lang)
        lang.set(qn('w:val'),'fa-IR'); lang.set(qn('w:bidi'),'fa-IR')
    return p
def para(text='', style=None, center=False):
    p=doc.add_paragraph(style=style); p.add_run(text); rtl(p, WD_ALIGN_PARAGRAPH.CENTER if center else WD_ALIGN_PARAGRAPH.RIGHT); return p
def heading(text, level=1):
    p=doc.add_heading(text, level=level); rtl(p); return p
def code(text):
    p=doc.add_paragraph(); p.paragraph_format.left_indent=Cm(.6); p.paragraph_format.right_indent=Cm(.6)
    p.paragraph_format.space_before=Pt(3); p.paragraph_format.space_after=Pt(8); p.alignment=WD_ALIGN_PARAGRAPH.LEFT
    r=p.add_run(text); r.font.name='Consolas'; r.font.size=Pt(9)
    rp=r._r.get_or_add_rPr(); rp.append(OxmlElement('w:noProof'))
    fonts=OxmlElement('w:rFonts'); fonts.set(qn('w:ascii'),'Consolas'); fonts.set(qn('w:hAnsi'),'Consolas'); rp.append(fonts)
    return p

p=doc.add_paragraph(style='Normal'); rtl(p, WD_ALIGN_PARAGRAPH.CENTER)
p.paragraph_format.space_before=Pt(8); p.paragraph_format.space_after=Pt(14)
r=p.add_run('افراز دقیق الفبا از ردپاهای مثبت و منفی با تعداد نامعلوم مؤلفه‌ها')
r.bold=True; r.font.size=Pt(20); r.font.color.rgb=RGBColor(31,78,121); rtl(p, WD_ALIGN_PARAGRAPH.CENTER)

heading('چکیده')
para('در این مقاله، مسئلهٔ افراز دقیق و متناهی‌نمونه‌ایِ عوامل منظمِ مستقل و مجزا را بررسی می‌کنیم؛ پذیرش واژهٔ کامل به‌صورت AND همهٔ مؤلفه‌ها تعریف می‌شود. ورودی شامل یک الفبای متناهیِ مرتب و صریح، و فهرست‌های متناهی ردپاهای مثبت و منفی است؛ تعداد مؤلفه‌ها و کران تعداد حالت‌ها داده نمی‌شود. یک افراز زمانی سازگار است که برای هر بلوک بتوان زبانی منظم یافت که تصویر همهٔ نمونه‌های مثبت را بپذیرد و ترکیب این زبان‌ها همهٔ نمونه‌های منفی را رد کند. معیار دقیق مبتنی بر تصویرها، گواه‌های متناهی برای عوامل، و شمارش همهٔ افرازهای سازگار با رشته‌های رشد محدودشدهٔ کانونی ارائه می‌شود. روش، بیشترین تعداد بلوک، تعداد افرازهای بهینه و گواه‌های مرتب و بازتولیدپذیر را نیز محاسبه می‌کند. کامل‌بودن الگوریتم پایه، ناورداهای انتخاب، گواه‌ها و خاتمهٔ متناهی آن در صورت وجود منابع کافی اثبات می‌شود؛ الفبای تهی هم پوشش داده می‌شود. دو بهینه‌سازی اختیاری با قرارداد خروجی یکسان جداگانه بررسی می‌شوند، اما هیچ‌کدام تضمین چندجمله‌ای عمومی نمی‌دهند. ممیزی‌های متناهی و زمان‌سنجی‌های محدود گزارش می‌شوند؛ این شواهد اثبات همگانی یا شناسایی سامانهٔ فیزیکیِ مولد نیستند.')

heading('۱. مقدمه و دستاوردها')
para('ممکن است یک ردپا رویدادهای چند زیرسامانهٔ ناشناخته را در خود داشته باشد. می‌پرسیم کدام افرازهای الفبای اعلام‌شده با مشاهده‌های متناهی و بدون نویز سازگارند، وقتی پذیرش به این معناست که هر عامل مستقل، تصویر ردپای خود را بپذیرد. چون تعداد مؤلفه‌ها K معلوم نیست، باید افرازهای دارای هر تعداد بلوک را بررسی کرد. هدف نمونه‌محورِ بازتولیدپذیر، بیشینه‌کردن تعداد بلوک‌های سازگار است؛ این انتخاب ثابت نمی‌کند که بلوک‌ها یا تعدادشان همان تجزیهٔ فیزیکی‌اند. روش پایه وجود زبان را به آزمون متناهیِ تصویرها تقلیل می‌دهد و سپس همهٔ افرازها را به ترتیب کانونی می‌گردد. خروجی، تعداد کل افرازهای سازگار را از شمار افرازهای بهینه جدا می‌کند و گواه‌های متناهیِ عوامل را می‌دهد. نتایج فقط برای مدل بولیِ تمام‌واژه، عوامل مستقل و بلوک‌های مجزا معتبرند؛ به برچسب‌های نویزی، سامانه‌های پیشوندبسته، لاگ‌های دلخواه، عوامل با تعداد حالت محدود، مشاهدهٔ جزئی، جریان نامتناهی یا عواملِ کوپل‌شده خودبه‌خود تعمیم نمی‌یابند. دربارهٔ عضویت واژه‌های مشاهده‌نشده نیز ادعایی نداریم.')

heading('۲. ورودی، معناشناسی و هدف')
para('الفبای مرتب متناهی را به‌صورت Σ=(a₁,…,aₘ) از شناسه‌های اتمیِ متمایز در نظر بگیرید. ترتیب ورودی تعیین‌کنندهٔ ترتیب کانونی است و متن شناسه‌ها مرتب‌سازی نمی‌شود. واژه، دنباله‌ای متناهی از نمادهای Σ است و ε واژهٔ تهی است. مجموعه‌های مثبت P و منفی N از فهرست‌های ورودی با حذف تکرارهای درون هر برچسب، همراه با حفظ نخستین رخداد، ساخته می‌شوند. تصویر π_B(w) برای B⊆Σ با حذف رویدادهای بیرون از B و حفظ ترتیب و تکرارهای باقی‌مانده تعریف می‌شود. تصویرگیری‌های متوالی ترکیب‌پذیرند: اگر B⊆D باشد، π_B(π_D(w))=π_B(w).')
para('افراز Π مجموعه‌ای از بلوک‌های ناتهی، دو‌به‌دو مجزا و با اجتماع Σ است. برای Σ=∅ تنها افراز، ∅ است. برای هر B∈Π زبان منظم F_B⊆B* در نظر می‌گیریم و زبان سراسری را چنین تعریف می‌کنیم:')
code('L(Π,(F_B)) = {w∈Σ* : ∀B∈Π, π_B(w)∈F_B}.     (1)')
para('عطف تهی درست است؛ بنابراین برای Σ=∅ زبان القاشده {ε} است. افراز نمونه‌سازگار است اگر P⊆L و N∩L=∅ برقرار باشد. خانوادهٔ افرازهای سازگار را 𝒱(P,N) می‌نامیم. اگر این خانواده تهی نباشد، کمیت‌های مسئله چنین‌اند:')
code('C = |𝒱(P,N)|,    k* = max{|Π| : Π∈𝒱(P,N)},\nO = |{Π∈𝒱(P,N) : |Π|=k*}|.                              (2)')
para('توصیه، نخستین افرازِ بیشینه‌بلوک در ترتیب کانونی است. C شمار همهٔ افرازها و O شمار بهینه‌هاست؛ هیچ‌کدام شمار ماشین‌ها یا احتمال‌ها نیستند. اگر 𝒱 تهی باشد، C=O=0 و k* و توصیه تعریف‌نشده‌اند.')
para('رکورد ورودی دقیقاً کلیدهای alphabet، positive و negative را دارد. الفبا آرایه‌ای از شناسه‌های رشته‌ایِ ناتهی و متمایز است و هر واژه آرایه‌ای از شناسه‌های کامل الفباست؛ [] برابر ε است. شناسه‌ها ممکن است یونیکد، نشانه‌گذاری یا فاصله داشته باشند و مقایسه دقیق است: شکستن رشته، تغییر بزرگی حروف یا نرمال‌سازی یونیکد انجام نمی‌شود. کلیدهای مفقود یا اضافی، نوع نادرست، شناسهٔ الفبای تهی یا تکراری و شناسهٔ ناشناخته در واژه، ورودی بدساخت‌اند. واژه‌ای که پس از نرمال‌سازی در هر دو مجموعه باشد، تناقضِ معتبرِ داده‌ای است.')
para('لم ۱ (نرمال‌سازی و تناقض). حذف تکرارهای درون هر برچسب خانوادهٔ افرازهای سازگار را تغییر نمی‌دهد؛ اگر P∩N ناتهی باشد هیچ افراز سازگاری وجود ندارد. دلیل: تکرار شرط تازه‌ای ایجاد نمی‌کند و واژه‌ای با دو برچسب متضاد باید هم پذیرفته و هم رد شود.')

heading('۳. معیار تصویر و گواه‌های منظم')
para('برای هر بلوک B تعریف می‌کنیم:')
code('H_B={π_B(p):p∈P}       و       R(B)={n∈N: π_B(n)∉H_B}.     (3)')
para('H_B متناهی است و ممکن است تهی باشد. این زبان منظم روی B است: می‌توان یک درخت پیشوند قطعی از پیشوندهای واژه‌های H_B ساخت و یک حالت چاهِ ردکننده افزود. از هر پیشوند، اگر گسترشِ برچسب‌خورده در درخت باشد به آن گره می‌رویم، وگرنه به چاه؛ انتقال‌های چاه به خودش بازمی‌گردند. تنها پیشوندهایی که خودشان در H_B هستند پذیرا علامت می‌خورند؛ بنابراین ε دقیقاً وقتی پذیرفته می‌شود که ریشه علامت خورده باشد. برای H_B تهی، یک حالت ردکننده با حلقهٔ خودکفا کافی است.')
para('قضیهٔ ۱ (معیار دقیق سازگاری). افراز Π سازگار است اگر و تنها اگر برای هر n∈N بلوکی B∈Π وجود داشته باشد که تصویر n روی آن با تصویر هیچ مثبت p برابر نباشد؛ به‌طور معادل، اجتماع R(B) برای B∈Π برابر N باشد. اگر عوامل سازگار موجود باشند، هر مثبت در همهٔ عوامل پذیرفته می‌شود، پس H_B⊆F_B؛ هر منفی نیز باید دست‌کم در یک عامل رد شود و در نتیجه تصویرش نمی‌تواند با تصویر مثبتی برابر باشد. برعکس، اگر شرط برقرار باشد، F_B=H_B را انتخاب می‌کنیم. این زبان‌های متناهی منظم‌اند، همهٔ مثبت‌ها را می‌پذیرند و برای هر منفی دست‌کم یک بلوک تصویر آن را رد می‌کند. برای Π=∅، شرط دقیقاً وقتی برقرار است که N=∅؛ این با قرارداد عطف تهی سازگار است.')
code('∀n∈N ∃B∈Π ∀p∈P: π_B(n)≠π_B(p)\n⇔  ⋃_{B∈Π} R(B)=N.                                      (4)')
para('اثبات: فرض کنید عوامل سازگار F_B موجود باشند. هر مثبت p با عطف پذیرفته می‌شود؛ پس برای هر B، تصویرش در F_B است و H_B⊆F_B. هر منفی n به‌وسیلهٔ عطف رد می‌شود، بنابراین دست‌کم یک بلوک B هست که تصویر n در F_B نیست؛ در نتیجه تصویر n نمی‌تواند با هیچ عضو H_B برابر باشد. پس شرط (4) برقرار است. برعکس، برای هر بلوک F_B=H_B بگذارید. H_B متناهی و بنابراین منظم است، حتی اگر تهی باشد. هر مثبت در همهٔ عوامل پذیرفته می‌شود. طبق (4)، برای هر منفی بلوکی وجود دارد که تصویرش از عامل مربوط بیرون است و در نتیجه عطف آن منفی را رد می‌کند. برای Π=∅، شرط (4) درست دقیقاً وقتی است که N=∅ و این با قرارداد عطف تهی سازگار است.')
para('ترتیب کمیت‌گذارها را نمی‌توان جابه‌جا کرد. برای Σ={a,b}، P={a,b} و N={ab}، منفی ab در هر مثبت روی یکی از تک‌نمادها تفاوت دارد؛ اما روی {a} با مثبت a و روی {b} با مثبت b برابر می‌شود. بنابراین {a}|{b} ناسازگار است، هرچند شرط «برای هر مثبت یک بلوکِ متمایزکننده وجود دارد» برقرار به نظر برسد. افراز تک‌بلوکی سازگار است.')
para('لم ۲ (گواه). برای افرازی که شرط (4) را برآورده کند، زبان‌های H_B و برای هر منفی یک بلوکِ ردکننده، گواه متناهی و مستقلاً قابل‌بازپخش می‌سازند. گواه شامل rgs و blocks و factors و negative_rejected_by است. بلوک‌ها برحسب برچسب کانونی مرتب می‌شوند؛ factors[i] تصاویر یکتای مثبت‌ها را به ترتیب نخستین رخداد برای بلوک متناظر نگه می‌دارد. برای هر منفی نرمال‌شده، اندیس صفرمِ نخستین بلوکِ ردکننده در negative_rejected_by ذخیره می‌شود. تکرارهای خام با همان ورودی نرمال‌شده پوشش داده می‌شوند. اگر منفی نباشد فهرست خالی است؛ برای افراز سازگارِ تهی، هر چهار آرایه تهی‌اند. این عوامل سازگاری را نشان می‌دهند، نه ماشین اصلیِ ناشناخته را.')
para('اثبات لم ۲: زبان‌های نمایش‌داده‌شده منظم‌اند و طبق ساخت، هر تصویر مثبت را می‌پذیرند. بلوک ثبت‌شده برای هر منفی، تصویر آن منفی را از زبان موضعی بیرون می‌برد، پس عطف سراسری منفی را رد می‌کند. خود افراز نیز با بررسی مجزاییِ بلوک‌های ناتهی، پوشش الفبا و جدا از هم بودن بلوک‌ها قابل بررسی است.')

heading('۴. شمارش کانونی افرازها')
para('برای m>0، رشتهٔ رشد محدودشده (RGS) برابر s=(s₁,…,sₘ) است به‌طوری‌که s₁=0 و برای i≥2، 0≤sᵢ≤1+max{s₁,…,sᵢ₋₁}. برای m=0 تنها RGS، رشتهٔ تهی است. هر بلوک به ترتیب نخستین نمادش در الفبای اعلام‌شده شماره می‌گیرد. برعکس، جایگاه‌های دارای یک برچسب در RGS یک بلوک می‌سازند.')
code('s₁=0,    0≤sᵢ≤1+max{s₁,…,sᵢ₋₁}    (2≤i≤m).          (5)')
para('لم ۳ (تناظر دوسویه). برچسب‌گذاریِ نخستین‌رخداد، بین افرازهای Σ و RGSهای طول m تناظر دوسویه برقرار می‌کند؛ حالت m=0 نیز افراز تهی و RGS تهی را شامل می‌شود. شرط رشد، برچسب‌ها را پیوسته از صفر نگه می‌دارد و هر برچسبِ استفاده‌شده پیش‌تصویر ناتهی دارد.')
para('اثبات: بلوک نماد نخست برچسب صفر می‌گیرد. هرگاه بلوک تازه‌ای برای نخستین بار ظاهر شود، برچسب آن دقیقاً یک واحد بیشتر از بیشینهٔ قبلی است؛ پس رشته شرط (5) را دارد. برعکس، شرط (5) برچسب‌های استفاده‌شده را از صفر پیوسته می‌کند. پیش‌تصویر هر برچسب ناتهی است و این پیش‌تصویرها مجزا هستند و جایگاه‌های الفبا را می‌پوشانند. برچسب‌گذاریِ نخستین‌رخدادِ این پیش‌تصویرها همان RGS اولیه را بازمی‌گرداند. حالت تهی بدیهی است.')
para('لم ۴ (تولید کامل واژه‌نامه‌ای). خطوط ۱ تا ۷ الگوریتم ۱ هر RGS را دقیقاً یک‌بار و به ترتیب واژه‌نامه‌ای می‌سازند. برای m=0 رشتهٔ تهی تولید می‌شود. در m>0 نخستین برچسب صفر است؛ اگر بیشینهٔ پیشوند q باشد، برچسب بعدی دقیقاً یکی از ۰ تا q+۱ است و به همین ترتیب پیمایش می‌شود. استقرا بر طول ادامه نشان می‌دهد همهٔ ادامه‌های معتبر، یکتا و مرتب ساخته می‌شوند.')
para('اثبات: اگر m=0 باشد خط ۲ فقط رشتهٔ تهی را می‌دهد. برای m>0 خط ۳ تنها مقدار مجاز جایگاه نخست را به کار می‌گیرد. در هر پیشوند با بیشینهٔ فعلی q، خطوط ۶ و ۷ دقیقاً برچسب‌های بعدی ۰ تا q+۱ را به ترتیب صعودی می‌گردند. استقرا روی طول باقی‌مانده نشان می‌دهد هر ادامهٔ معتبر یک‌بار ظاهر می‌شود و همهٔ رشته‌های دارای برچسب بعدی کوچک‌تر، پیش از رشته‌های دارای برچسب بزرگ‌تر قرار می‌گیرند. پس تولید کامل، یکتا و واژه‌نامه‌ای است.')

doc.add_page_break()
heading('۵. الگوریتم ۱: روش پایهٔ دقیق و جامع')
para('الگوریتم زیر هر نامزد را در برابر همهٔ مثبت‌ها و منفی‌های نرمال‌شده می‌سنجد. شمارنده‌ها دقت دلخواه دارند و حداکثر دو گواه از هر خانوادهٔ تعریف‌شده نگه داشته می‌شود. نتیجهٔ INCOMPATIBLE شمارهای صفر و بدون توصیه دارد؛ ورودی نامعتبر، محاسبهٔ ناتمام و خطای بازپخش، فیلدهای نتیجهٔ ریاضی ندارند.')
code('01  GENERATE(m):\n02      اگر m=0: [] را تولید کن؛ بازگرد\n03      از EXTEND([0],0,m) خروجی بگیر\n04  EXTEND(s,q,m):\n05      اگر |s|=m: s را تولید کن؛ بازگرد\n06      برای x=0,1,…,q+1 به‌ترتیب:\n07          EXTEND(s·[x], max(q,x), m) را تولید کن\n08  CHECK(Σ,P,N,s):\n09      بلوک‌ها ← پیش‌تصویرهای ناتهیِ برچسب‌های s به ترتیب Σ\n10      برای هر بلوک B: H[B] ← {projection(p,B):p∈P}\n11      rejecting ← فهرست تهی\n12      برای هر n∈N به ترتیب ورودی نرمال‌شده:\n13          نخستین B را در ترتیب برچسب بلوک بیاب که projection(n,B)∉H[B]\n14          اگر چنین بلوکی نیست: FAIL را برگردان\n15          index(B) را به rejecting بیفزا\n16      witness(s,blocks,H,rejecting) را برگردان\n17  EXACT(record):\n18      رکورد و شناسه‌ها را اعتبارسنجی کن؛ اگر بدساخت بود: INVALID_INPUT\n19      Σ,P,N ← ورودی نرمال‌شده؛ تکرارهای هر برچسب را حذف کن\n20      اگر P∩N≠∅: INCOMPATIBLE با شمارهای صفر را برگردان\n21      C←0؛ O←0؛ best←NONE؛ all_witnesses←[]؛ opt_witnesses←[]\n22      برای هر s که GENERATE(|Σ|) تولید می‌کند:\n23          w←CHECK(Σ,P,N,s)\n24          اگر w=FAIL: ادامه بده\n25          C←C+1\n26          اگر طول all_witnesses<2: w را به آن بیفزا\n27          k←تعداد بلوک‌های w\n28          اگر best=NONE یا k>best:\n29              best←k؛ O←1؛ opt_witnesses←[w]\n30          وگرنه اگر k=best:\n31              O←O+1\n32              اگر طول opt_witnesses<2: w را به آن بیفزا\n33      اگر C=0: INCOMPATIBLE با شمارهای صفر را برگردان\n34      گواه‌های نگه‌داشته‌شده را بازپخش کن؛ اگر شکست خورد: ERROR\n35      status←UNIQUE_COMPATIBLE اگر C=1، وگرنه AMBIGUOUS\n36      status,C,best,O,(O=1),opt_witnesses[0],\n37          all_witnesses,opt_witnesses را برگردان')
para('لم ۵ (درستی CHECK). برای هر RGS تولیدشده، خطوط ۸ تا ۱۶ دقیقاً در صورت ناسازگاری افراز متناظر FAIL برمی‌گردانند و در غیر این صورت گواهی معتبر را با ترتیب کانونی بلوک‌ها و ترتیب منفی‌ها می‌سازند. اثبات: خطوط ۹ و ۱۰ بلوک‌ها و H_Bهای هرکدام را می‌سازند. برای هر منفی نرمال‌شده، خطوط ۱۲ تا ۱۴ وجود بلوکی را لازم می‌دانند که تصویرش بیرون از کل H_B باشد. قضیهٔ ۱ همین شرط را لازم و کافی می‌داند. اگر چنین بلوکی باشد، خط ۱۳ نخستین بلوک را انتخاب و خط ۱۵ اندیسش را ذخیره می‌کند. خط ۱۶ تصاویر مثبت را به ترتیب نخستین رخداد می‌سازد و گواه لم ۲ را برمی‌گرداند.')
para('لم ۶ (ناوردای پیشوند). پس از هر پیشوند پیمایش RGS، C تعداد نامزدهای سازگارِ دیده‌شده و all_witnesses شامل نخستین min(2,C) گواه به ترتیب واژه‌نامه‌ای است. اگر C>0، best بیشترین تعداد بلوک، O تعداد نامزدهای دارای best و opt_witnesses شامل نخستین min(2,O) گواه بهینه است. اثبات: در آغاز C=O=0 و فهرست‌ها تهی‌اند، پس ناوردا برقرار است. طبق لم ۵، بررسی ناموفق نامزد سازگار نیست و خط ۲۴ ناوردا را تغییر نمی‌دهد. در غیر این صورت RGS تازه طبق لم ۴ سازگار و یکتا است؛ خطوط ۲۵ تا ۲۷ آن را می‌شمارند و تنها اگر کمتر از دو گواه قبلی ذخیره شده باشد آن را نگه می‌دارند. اگر شمار بلوک k از best بیشتر باشد، همهٔ بهینه‌های پیشین برای پیشوند فعلی از بهینگی خارج می‌شوند؛ خط ۲۹ best=k و O=1 می‌گذارد و فهرست را با نامزد فعلی جایگزین می‌کند. اگر k=best، خط ۳۱ O را زیاد می‌کند و خط ۳۲ فقط در صورت کمتر بودن تعداد گواه‌های ذخیره‌شده از دو، گواه را می‌افزاید. اگر k<best باشد، مقدار بهینه و گواه‌هایش تغییر نمی‌کنند. چون شمارش واژه‌نامه‌ای است، گواه‌های نگه‌داشته‌شده همان دو مورد نخست‌اند. استقرا ناوردا را ثابت می‌کند.')
para('قضیهٔ ۲ (درستی، کامل‌بودن و بهینگی). برای ورودی متناهیِ درست‌ساخت و منابع کافی، اگر شمارش کامل و بازپخش موفق باشد، الگوریتم دقیقاً وقتی INCOMPATIBLE می‌دهد که افراز سازگاری وجود نداشته باشد. در غیر این صورت C، best، O، وضعیت، توصیه و دو فهرست گواه مطابق تعریف‌اند و توصیه نخستین RGS بهینه است. اثبات: اعتبارسنجی و نرمال‌سازی به‌واسطهٔ لم ۱ مجموعه‌های ورودی را حفظ می‌کنند؛ بازگشت زودهنگامِ برچسب‌های متناقض نیز به همان لم درست است. در غیر این صورت، لم ۴ هر افراز را یک بار تولید و لم ۵ دقیقاً افرازهای سازگار را علامت‌گذاری می‌کند. در پایان حلقه، ناوردای پیشوند لم ۶ کل خانواده را توصیف می‌کند. اگر C=0 باشد، خط ۳۳ ناسازگاری را درست اعلام می‌کند. اگر C>0 باشد، best و O معنای سراسری لازم را دارند، opt_witnesses[0] نخستین RGS بهینه است و هر دو فهرست دقیقاً نخستین min(2,count) نامزد را دارند. لم ۲ گواه‌های عوامل منظم متناهی را معتبر می‌کند. خطوط ۳۴ تا ۳۷ خروجی کامل خواسته‌شده را برمی‌گردانند. اگر بازپخش شکست بخورد، ERROR بازمی‌گردد و فرض بازپخش موفق قضیه برقرار نیست.')
para('نتیجهٔ ۱ (وضعیت و تساوی). در خروجی کامل و شدنی، UNIQUE_COMPATIBLE دقیقاً وقتی برقرار است که C=1 و AMBIGUOUS وقتی C≥2؛ اما optimal_unique فقط می‌گوید O=1 و مفهوم جداگانه‌ای است. برای Σ={a,b} و P={ε} و N={a}، هم افراز تک‌بلوکی و هم دو بلوکی سازگارند، ولی دومی تنها بهینه است؛ بنابراین C=2 و O=1.')
para('اثبات: دو وضعیت، حالت‌های ممکن خانوادهٔ دقیق با اندازهٔ C را پوشش می‌دهند؛ پرچم یکتایی بهینه از زیرمجموعهٔ بیشینه‌ای محاسبه می‌شود که جداگانه شمرده شده است. در مثال بالا، تنها افراز دو بلوکی بهینه است؛ پس یکتاییِ بهینه به معنی یکتاییِ سازگاری نیست.')
heading('وابستگی اثبات‌ها به خطوط الگوریتم',2)
para('خطوط ۱ تا ۷: لم‌های ۳ و ۴ یکتایی، ترتیب و کامل‌بودن تولید RGS، از جمله m=0، را می‌دهند. خطوط ۸ تا ۱۶: قضیهٔ ۱ و لم ۵ آزمون دقیق تصویر و ساخت گواه متناهی را ثابت می‌کنند. خطوط ۱۷ تا ۲۰: لم ۱ و اعتبارسنجی کل رکورد، ساختار نامعتبر را از برچسب‌های متناقض جدا می‌کنند. خطوط ۲۱ تا ۲۷: لم ۶ شمار همهٔ سازگارها و دو گواه نخست برای پیشوند پیموده‌شده را اثبات می‌کند. خطوط ۲۸ تا ۳۲: لم ۶ بازنشانی بیشینه، شمار تساوی بهینه و گواه‌های بهینهٔ واژه‌نامه‌ای را ثابت می‌کند. خطوط ۳۳ تا ۳۷: قضیهٔ ۲ و نتیجهٔ ۱ وضعیت نهایی، خروجی دقیق و مدیریت خطای بازپخش را توجیه می‌کنند. بیرون از حلقه: بخش ۷ رفتار محاسبهٔ محدود و پایان غیرقابل‌گرفتن را تعریف می‌کند؛ محاسبهٔ ناتمام هیچ ادعای دقیقی ندارد.')

heading('۶. انطباق با پیاده‌سازی تثبیت‌شده')
para('مولد بازگشتی در شبه‌کد مفهومی است. کد پایتون تثبیت‌شده از جانشین واژه‌نامه‌ایِ تکرارشونده استفاده می‌کند: از RGS تمام‌صفر آغاز می‌کند، راست‌ترین جایگاهی را می‌یابد که با پیشوند ثابت بتوان برچسبش را افزایش داد، آن را یک واحد زیاد می‌کند و پسوند را صفر می‌گذارد. لم ۷ می‌گوید این مولد دقیقاً همان رشته‌ها را به همان ترتیب می‌دهد و ساخت گواه با تأخیر، روی ورودی ثابت همان گواه ساختِ فوری را تولید می‌کند. هر رشتهٔ بزرگ‌تر باید در جایگاهی تغییر کند که پیشوندش معتبر بماند؛ تغییر راست‌ترین جایگاه ممکن و افزایش حداقلی، کوچک‌ترین جانشین را می‌دهد و پسوند صفر، کمترین تکمیل معتبر است. اگر هیچ جایگاهی افزایش‌پذیر نباشد، رشتهٔ بزرگ‌تری وجود ندارد. بازبین داخلی پوشش بلوک‌ها، تطبیق RGS کانونی، برابری مجموعهٔ عوامل، پذیرش مثبت‌ها و رد منفی به‌وسیلهٔ بلوک ارجاع‌شده را می‌سنجد؛ ترتیب سریال‌سازی مثبت‌ها و «نخستین» بودن بلوک ردکننده را مستقلاً نمی‌سنجد، اما این دو ویژگی از سازندهٔ کد نتیجه می‌شوند و در ممیزی مستقل نیز بررسی شده‌اند.')

heading('۷. خاتمه، پیچیدگی و معنای خطاها')
para('قضیهٔ ۳ (خاتمهٔ متناهی). برای هر ورودی متناهیِ درست‌ساخت، الگوریتم با منابع نامحدود به نتیجهٔ دقیق یا ناسازگاریِ موجه از نظر ریاضی ختم می‌شود. الفبای متناهی فقط تعداد متناهی افراز دارد و مولد هر یک را یک‌بار تولید می‌کند؛ هر تصویرگیری، مقایسه، اعتبارسنجی، به‌روزرسانی شمارنده، ساخت گواه و بازپخش روی اشیای متناهی خاتمه می‌یابد.')
para('تعداد افرازها Bell(m) است و Bell(0)=1. اجرای کاملِ پایه، مگر آن‌که تناقض برچسب‌ها زودتر پیدا شود، دقیقاً Bell(m) نامزد را می‌سنجد. هزینهٔ هر نامزد چندجمله‌ای در اندازهٔ صریح ورودی است؛ پس کران محافظه‌کارانه Bell(m) ضرب‌در یک عامل چندجمله‌ای است، نه تضمین زمان چندجمله‌ای برای m متغیر. گواه‌های نگه‌داشته‌شده و وضعیت RGS متناهی‌اند و شمارهای دقیق می‌توانند تا Bell(m) رشد کنند و O(log Bell(m)) بیت بخواهند. ورودی متناهیِ بزرگ ممکن است از زمان یا حافظهٔ موجود فراتر رود.')
para('اعتبارسنجی کل رکورد پیش از نتیجهٔ ریاضی انجام می‌شود. INVALID_INPUT یعنی ساختار یا شناسه‌ها نامعتبرند، نه این‌که داده تناقض دارد. واژهٔ معتبر با برچسب مثبت و منفی INCOMPATIBLE است؛ همچنین اگر پیمایش کامل هیچ افراز سازگاری نیابد همین وضعیت موجه است. برای m>0 و P∩N=∅، افراز تک‌بلوکی همواره سازگار است، چون تصویر الفبای کامل همان واژه است. برای m=0، سازگاری دقیقاً وقتی برقرار است که N=∅؛ در این حالت C=O=1 و best=0. حالت‌های P یا N تهی، ε، نمادهای استفاده‌نشده، تکرار واژه‌ها و ردپاهای متناهی با طول دلخواه نیاز به بریدن داده ندارند.')
para('گزینهٔ max_candidates تعداد نامزدهای بازرسی‌شده را محدود می‌کند، نه K یا تعداد حالت‌ها. با پایان بودجه، وقفهٔ صفحه‌کلیدِ گرفته‌شده یا کمبود حافظهٔ گرفته‌شده، INCOMPLETE با فیلدهای ریاضی تهی برمی‌گردد؛ هیچ شمار جزئی یا بیشینه‌ای گواهی نمی‌شود. شکست بازپخش ERROR می‌دهد. فرایندی که به‌سختی خاتمه داده شود یا نتواند حتی خطا بسازد ممکن است پاسخی ندهد. محاسبهٔ غایب یا زمان‌پایان‌یافته به‌تنهایی شاهد ناسازگاری نیست.')

heading('۸. بهینه‌سازی دقیق اختیاری A گواه خانوادهٔ کامل')
para('پس از اعتبارسنجی ورودی و رسیدگی به تناقض برچسب‌ها، اگر کاربر محدودیت صریحی برای تعداد نامزدها نداده باشد، افراز تک‌نمادی S آزموده می‌شود. ناسازگاری آن تنها باعث بازگشت به روش پایه می‌شود و هیچ نتیجهٔ زودهنگامی نمی‌دهد. سازگاری S امکان استفاده از گواه خانوادهٔ کامل را فراهم می‌کند.')
para('پس از اعتبارسنجی و بررسی تناقض، اگر بودجهٔ نامزد صریحی وجود نداشته باشد، افراز تک‌نمادی S بررسی می‌شود. اگر سازگار نباشد، روش پایه اجرا می‌شود و نتیجهٔ زودهنگام گرفته نمی‌شود؛ اگر سازگار باشد، گواه خانوادهٔ کامل به کار می‌رود. لم ۸ (یکنواختی در ادغام) می‌گوید اگر B⊆D و n∈R(B)، آنگاه n∈R(D)، و در نتیجه هر درشت‌سازیِ افراز سازگار نیز سازگار است. اگر تصویر منفی روی D با تصویر مثبتی برابر بود، تصویرگیری بیشتر روی B برابری را حفظ می‌کرد و با n∈R(B) تناقض داشت؛ پس مانع رد در بلوک ادغام‌شده باقی می‌ماند.')
para('نتیجهٔ ۲. برای الفبای ناتهی و P,N مجزا، افراز تک‌بلوکی سازگار است. اگر افرازی چندبلوکی سازگار باشد، C≥2؛ بنابراین یکتایی سازگاری فقط می‌تواند برای افراز تک‌بلوکی رخ دهد. عکس آن نمی‌گوید بهینهٔ یکتا یعنی افراز سازگار یکتا. قضیهٔ ۴ می‌گوید اگر S سازگار باشد، همهٔ افرازها سازگارند؛ تعدادشان Bell(m)، بیشینهٔ بلوک m و تنها افراز بیشینه، S است. نخستین RGS، 0^m و اگر m≥2 دومین، 0^(m−1)1 است. برای m=0 یا 1 افراز دومی وجود ندارد. اعداد بل با S(0,0)=1 و رابطهٔ S(i,k)=S(i−1,k−1)+kS(i−1,k) و Bell(m)=Σ_k S(m,k) محاسبه می‌شوند. این رابطه O(m²) عملیات حسابی و O(m) مقدار ذخیره‌شده می‌خواهد؛ هزینهٔ اعداد صحیح بزرگ ثابت نیست. گواه خانوادهٔ کامل، گواه‌ها را طبق قواعد پایه می‌سازد و بازبینی می‌کند، اما ادعا نمی‌کند Bell(m) نامزد واقعاً بررسی شده است. با هر max_candidates صریح، حتی صفر، بهینه‌سازی A کنار گذاشته می‌شود تا مرز بودجهٔ پایه حفظ شود.')

heading('۹. بهینه‌سازی دقیق اختیاری B حافظهٔ نهان محدود بلوک‌ها')
para('برای هر منفی n_j و بلوک B، بردار بولی V_B چنین تعریف می‌شود: V_B[j]=true اگر و تنها اگر π_B(n_j)∉H_B. حافظهٔ نهان LRU محدود به ۲۵۶ بردار و مختص به هر فراخوانی، از تاپل شناسه‌های کامل با ترتیب الفبای اعلام‌شده به‌عنوان کلید استفاده می‌کند. در خطای حافظهٔ نهان، همهٔ درایه‌ها از ورودی نرمال‌شدهٔ ثابت محاسبه می‌شوند؛ حذف از حافظه فقط دادهٔ ذخیره‌شده را دور می‌اندازد. افراز دقیقاً وقتی پذیرفته می‌شود که برای هر منفی، دست‌کم یکی از بلوک‌ها درایهٔ درست داشته باشد.')
para('قضیهٔ ۵ (هم‌ارزی حافظهٔ نهان). جایگزینی آزمون پایه با آزمون حافظهٔ محدود، برای همان ورودی و بودجه، خروجی کامل را حفظ می‌کند؛ از جمله C و best و O و وضعیتِ سازگاری همگانی و RGS کانونی و دو خانوادهٔ گواه مرتب، مشروط بر آن‌که وقفهٔ منابع رخ ندهد. چون هر V_B دقیقاً عضویت در R(B) را بیان می‌کند و از تاریخچهٔ پیمایش مستقل است، اصابت، خطا یا حذف حافظه نتیجهٔ بولی را تغییر نمی‌دهد. پوشش اجتماع بردارها معادل قضیهٔ ۱ است؛ ترتیب نامزدها هم ثابت می‌ماند، پس استقرای ناوردای لم ۶ شمارها و گواه‌ها را حفظ می‌کند. بودجهٔ صریح، A را کنار می‌گذارد و B می‌تواند بدون تغییر پیشوند بررسی‌شده به کار رود. A و B مستقل یا همزمان‌اند. حافظه محلیِ حل‌گر است و واقعیت نمونه‌های پیشین را وارد نمی‌کند. سقف ۲۵۶ فقط بردارهای ذخیره‌شده را محدود می‌کند، نه نمادها یا تعداد نامزدها؛ بلوک حذف‌شده دوباره محاسبه می‌شود. پرکردن بردار کامل ممکن است از توقف زودهنگام پایه پرهزینه‌تر باشد و هر دو بهینه‌سازی می‌توانند سربار حافظه یا زمان بیفزایند.')
para('اثبات: برای P,N نرمال‌شدهٔ ثابت و B ثابت، (6) همان عضویت در R(B) از (3) است و به بلوک‌های دیگر یا سابقهٔ شمارش وابسته نیست. اصابت، همان بردار محاسبهٔ تازه را می‌دهد؛ در خطای حافظه یا پس از اخراج نیز دوباره محاسبه می‌شود. پوشش اجتماع اندیس‌های منفی در نتیجه با (4) هم‌ارز است، از جمله در حالت بی‌منفی N=∅ و افراز تهی Π=∅. برای هر نامزد در ترتیب تغییرنکردهٔ RGS تصمیم بولی یکسانی گرفته می‌شود؛ پس استقرای لم ۶ C و best و O و RGSهای حفظ‌شده را یکسان می‌کند. سازنده و بازبین قطعیِ گواه‌ها سریال‌سازی یکسان می‌دهند. بررسی بودجه نیز در همان مرز نامزد انجام می‌شود.')

heading('۱۰. شناسایی‌پذیری و محدودیت‌ها')
para('افراز بیشینه، توصیه‌ای دقیق بر اساس نمونه است، نه گواه تجزیهٔ فیزیکیِ اصلی. برای Σ={a,b}، یک عامل همگانی Σ* و دو عامل همگانی تک‌نمادی a* و b* همگی زبان کامل Σ* را می‌سازند؛ بنابراین افرازهای متفاوت حتی با همهٔ مشاهده‌های عضویت ممکن است تمایزپذیر نباشند، مگر فرض‌های بیشتری افزوده شود. اگر مولد واقعی در مدل مقرر باشد، برچسب‌ها را برازش دهد و دقیقاً یک افراز سازگار باشد، آن افراز باید همان افراز واقعی باشد؛ اما این نتیجهٔ شرطی پیاده‌سازی عوامل، نام دستگاه‌ها یا برچسب‌ها را تعیین نمی‌کند. O=1 به‌تنهایی از C=1 ضعیف‌تر است. روش فقط برای ورودی‌های متناهی با نمادهای مشخص و برچسب‌های بولیِ تمام‌واژه دقیق است. K فیزیکی، رفتار مشاهده‌نشده یا همهٔ ردپاهای آینده را استنباط نمی‌کند و پایان‌پذیری هر اجرای قطع‌شده را تضمین نمی‌کند. نویز، کمینه‌بودن حالت، بسته‌بودن پیشوندی، همگام‌سازی بین بلوک‌های هم‌پوشان و لاگ‌های واقعیِ بی‌مدل، موضوع این کار نیستند. برای بهینه‌سازی کلی با الفبای متغیر، زمان چندجمله‌ای ادعا نمی‌شود.')

heading('۱۱. اعتبارسنجی و رفتار اندازه‌گیری‌شده')
para('نسخهٔ پایهٔ C028 با یک مرجع مستقلِ درج در مجموعه برای افرازها ممیزی شد که از مولد RGS آن مستقل بود. ممیزی پس از روشن‌شدن قرارداد سریال‌سازی، ۲۱۸۷ برچسب‌گذاری جامع سه‌حالته از هفت واژهٔ طول حداکثر دو روی الفبای دونمادی، ۶۰ مورد بذرگذاری‌شده با ۳ تا ۸ نماد، ۱۹ ورودی مرزی، ۱۱ کنترل طرح‌وارهٔ نامعتبر و سه کنترل نمونهٔ DFA پنهان را گذراند. آزمون‌های دگرریختی، بازپخش گواه و بودجه نیز موفق بودند. کنترل ۱۲۰۰ شناسه‌ای عمداً پس از یک نامزد متوقف شد و حل جامعِ الفبای بزرگ نبود. یک بررسی‌گر اولیه به‌اشتباه جایگاه‌های خامِ منفی تکراری را به‌جای اندیس‌های نرمال‌شده شمرد؛ شکست ثبت شد، قرارداد سریال‌سازی روشن شد و همان نسخهٔ پایه دوباره اجرا شد. این ممیزی متناهی شاهدی برای پیاده‌سازی است، نه اثبات همهٔ ورودی‌ها.')
para('ممیزی نامزد C030 جداگانه بود: هر یک از حالت‌های A تنها، B تنها و A+B با مرجع مستقل در ۲۲۷۱ ورودی بدون محدودیت تطبیق کرد؛ همچنین برای هر گونه، هشت آزمون بودجهٔ صریح و نه آزمون طرح‌واره/بودجهٔ نامعتبر، خروجی کامل را با پایه مقایسه کرد و گواه‌ها را بازپخش کرد. آزمون تشخیصی نه‌نمادی ۳۶۶ حذف LRU و ۱۱۱ درج دوباره دید. در یک آزمون شکست زودهنگام، پایه ۶ و B ده بار تصویرگیری کرد، اما تصمیم یکسان بود. نخستین اجرای C030 در یک بررسیِ ثابتِ خودِ harness شکست خورد؛ شکست نگه داشته شد، آزمون تشخیصی اصلاح و مستقل بررسی شد، سپس کد نامزدِ بدون تغییر آزمون را گذراند. فیلد قدیمی candidate_calls: 0 در JSON ممیزی، اثر حالت اجرای پایه است؛ شمارنده‌های هر گونه، مقایسه‌های واقعی نامزدها را ثبت می‌کنند.')
para('پس از بررسی درستی، ماتریس زمان‌سنجی هشت‌موردیِ پایه در برابر نسخهٔ ترکیبی، برای هر حل‌گر و ورودی سه فرایند تازه اجرا کرد؛ هر ۴۸ اجرا کامل شدند و بررسی کامل خروجی را گذراندند. زمان آغاز فرایند هم حساب شد. میانهٔ نسخهٔ ترکیبی در سه مورد از هشت مورد بیشتر و در پنج مورد کمتر بود؛ با فقط سه مشاهده در هر خانه و تغییرپذیری قابل‌توجه، این اندازه‌گیری‌ها سرعت‌بخشی عمومی را ثابت نمی‌کنند و اثر هر بهینه‌سازی را جدا نمی‌سنجند. A تنها و B تنها جداگانه زمان‌سنجی نشدند و حافظه اندازه‌گیری نشد. پایهٔ تغییرنیافتهٔ C028 همچنان پیش‌فرض پیشنهادی است و گونه‌های C030 آزمایشی‌اند. زمان‌های خام، شکست‌ها، ورودی‌ها، فرمان‌ها و هش‌ها در پیوست الف معرفی می‌شوند.')

heading('۱۲. نسبت با کارهای پیشین')
para('مانع مبتنی بر تصویر با کار هنری و همکاران دربارهٔ یادگیری ترکیبیِ خودکارها ارتباط نزدیک دارد: در بخش ۴٫۱، گزارهٔ ۵ و بخش ۶٫۱، نتیجهٔ ۱۲ از [۳] ناسازگاری را از راه مشاهدهٔ منفی‌ای توصیف می‌کند که تصویرهایش روی همهٔ الفباهای محلی با مشاهده‌های مثبت سازگارند. آن کار به یادگیری فعال سامانه‌های گذار برچسب‌خورده می‌پردازد و توزیع‌های هم‌پوشان و همگام‌سازی را مجاز می‌داند؛ صورت‌بندی کلی‌اش با مسئلهٔ غیرفعالِ افراز عوامل مجزای این مقاله یکسان نیست. تازگی معیار ادعا نمی‌شود. شمارش واژه‌نامه‌ای افراز مجموعه‌ها در ادبیات ترکیبیاتی سابقه دارد [۴] و شمارش بل/استرلینگ استاندارد است [۱،۲]. مورمن [۵] یادگیری فعال ماشین‌های مور با خروجی‌های تجزیه‌پذیر را بررسی می‌کند، نه هدف افراز الفبای سازگار با نمونهٔ حاضر. الگوریتم‌های پوشش دقیق و شمارش مرتبط نیز در زمینه‌های گسترده‌تر موجودند [۶]، اما لزوماً شمار دقیق خانواده، دو گواه برچسب‌دار نخست و معنای وقفهٔ این مقاله را تأمین نمی‌کنند. این مقایسه محدود است و جست‌وجوی جامع تازگی یا تضمین پذیرش انتشار نیست.')

heading('۱۳. نتیجه‌گیری')
para('معیار دقیق سازگاری و شمارش جامعِ کانونی، مسئلهٔ متناهیِ نمونه‌ایِ مشخص با K نامعلوم را هرگاه منابع کافی باشد حل می‌کنند. اثبات‌ها شمار دقیق، بهینهٔ کانونی، ترتیب گواه‌ها و تحقق‌های منظم متناهی را توجیه می‌کنند؛ گواه خانوادهٔ کامل و حافظهٔ نهان نیز تحت شرایط خود همین قرارداد را نگه می‌دارند. آزمون متناهی و بهینه‌سازی هدف نمونه‌ای، به‌طور کلی مالکیت فیزیکی را بازیابی نمی‌کنند. ادعاهای بیشتر نیازمند فرض‌های اضافی، مرور گسترده‌تر ادبیات، شواهد آزمایشی مناسب و داوری مستقل‌اند.')

heading('پیوست الف. بازتولیدپذیری و منشأ')
para('نسخهٔ پایهٔ تثبیت‌شده در results/2026-11-11/exact_foundations_v28/implementation/reference.py با SHA-256 برابر 5f60b27447b37ec07f1fd6bce75be6199b898573d4b32e90413e900e3a615a94 است. مشخصات، اثبات، اصلاحات سریال‌سازی و شبه‌کد در پوشهٔ theory و فایل PSEUDOCODE.md همان نسخه آمده‌اند؛ شواهد آزمون مستقل در AUDIT_REPORT_V2.md و AUDIT_MANIFEST_V2.json ثبت شده‌اند. نامزد اختیاری در results/2026-11-11/review_optimization_v30/optimization/candidate_v1.py با SHA-256 برابر 7501901c6de5d7bb78ffc60f152b818733e3bd4460c9a655b8d783f384e8fc2b است. اثبات پیشنهاد، رأی بررسی منبع، گزارش نهایی و ممیزی آن در پوشه‌های optimization و review و فایل‌های گزارش و ممیزی قرار دارند. مانیفست ممیزی نسخهٔ دوم، فرمان‌ها، نسخهٔ اجراکننده‌ها، هش مجموعه‌داده و منابع و شکست ثبت‌شده را نگه می‌دارد؛ timing_results.json زمان‌های خام و خروجی کامل حل‌گرها را ثبت می‌کند. بازبین‌های اثبات و منبع و ممیز، عامل‌های هوش مصنوعی بودند، نه داوران انسانی یا ابزار اثبات صوری. برای این بهینه‌سازی، منبع پایه یا نقطهٔ ورود عمومی تغییر داده نشد.')

